import { el, card, button, field, input, alertBox, spinner } from '../core/dom.js';
import { fetchRoot, verifyCredentials } from '../api/client.js';
import { saveSession, normalizeUrl } from '../core/session.js';
import { runtimeConfig } from '../core/runtime-config.js';
import { navigate } from '../core/router.js';
export function renderLogin(){const server=input(runtimeConfig.apiUrl||window.location.origin,{type:'url',required:true,placeholder:'https://api.exemplo.com.br'});const key=input('',{type:'password',required:true});const error=el('div');const submit=button('Entrar',{class:'primary full'});const form=el('form',{class:'form-stack'},field('Servidor',server),field('Chave da API',key),error,submit);form.onsubmit=async(e)=>{e.preventDefault();submit.disabled=true;submit.replaceChildren(spinner(),'Validando...');error.replaceChildren();try{const apiUrl=normalizeUrl(server.value);const root=await fetchRoot(apiUrl);await verifyCredentials(apiUrl,key.value);saveSession({apiUrl,apiKey:key.value,version:root.version||'',clientName:root.clientName||'',documentationUrl:runtimeConfig.documentationUrl||root.documentation||''});navigate('/manager/');}catch(err){error.replaceChildren(alertBox(err.message||String(err)));}finally{submit.disabled=false;submit.textContent='Entrar'}};return el('div',{class:'login-page'},el('div',{class:'login-wrap'},el('img',{class:'login-logo',src:'/assets/images/argws-connect-logo-horizontal.svg',alt:'Connect|API'}),card(el('h1',{text:'Acessar Manager'}),el('p',{class:'muted',text:'Informe o endereço da API e a chave de acesso.'}),form)))}
